examples.code:
#include <memory>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    alignas(64) int values[16]{};
    int *pointer = std::assume_aligned<64>(values);
    pointer[0] = 42;
    assert(values[0] == 42);
}
